msg.connections = global.get("parat_bridge.connections");
const utils = global.get("utils");

const rayvn_log_id = msg.payload.rayvn_configured.log_id;
const wasos_chat = msg.payload.wasos_configured.chatroom_name;

if (!rayvn_log_id || !wasos_chat) {
    node.error("Missing configuration")
    return [null, null]
}

const connection_id = utils.hash_code(rayvn_log_id + wasos_chat)

// Check if this exact pairing already exists
const existing = msg.connections.find(c => c.id === connection_id);

if (existing) {
    msg.existing_connection = existing; 
    return [msg, null];
} else {
    msg.connection_id = connection_id
    return [null, msg];
}

const rayvn_config = msg.payload.rayvn_configured;
const wasos_config = msg.payload.wasos_configured;

msg.existing_connection.rayvn = {
    api_key: rayvn_config.api_key,
    log_name: rayvn_config.log_name,
    timestamp: Date.now(),
    log_id: rayvn_config.log_id
};
msg.existing_connection.wasos = {
    username: wasos_config.username,
    user_id: wasos_config.user_id,
    chatroom_name: wasos_config.chatroom_name,
    timestamp: Date.now(),
    group: wasos_config.group,
    api: {
        key: wasos_config.api.key,
        expires: wasos_config.api.expires
    }
};
msg.existing_connection.active = true;

global.set("parat_bridge", global.get("parat_bridge"));
node.log("Updated existing connection: " + msg.existing_connection.label);

msg.payload = msg.existing_connection;
return msg;

const rayvn_config = msg.payload.rayvn_configured;
const wasos_config = msg.payload.wasos_configured;

const connection = {
    id: msg.connection_id,
    name: rayvn_config.log_name + "_" + wasos_config.chatroom_name,
    time_created: Date.now(),
    rayvn: {
        api_key: rayvn_config.api_key,
        log_name: rayvn_config.log_name,
        log_id: rayvn_config.log_id,
        timestamp: Date.now()
    },
    wasos: {
        username: wasos_config.username,
        user_id: wasos_config.user_id,
        chatroom_name: wasos_config.chatroom_name,
        group: wasos_config.group,
        timestamp: Date.now(),
        api: {
            key: wasos_config.api.key,
            expires: wasos_config.api.expires
        }
    },
    active: true,
    master_log: [],
};

// 
const data = global.get("parat_bridge");
data.connections.push(connection);
global.set("parat_bridge", data);

node.log("Created new connection: " + connection.label);

msg.connection = connection;
msg.payload = connection;

return msg;
